'use client';

import { useEffect, useRef, useState } from 'react';
import { toPng } from 'html-to-image';

export interface CardMember {
  id: string;
  name: string;
  father_name: string;
  cnic?: string | null;
  b_form?: string | null;
  phone?: string | null;
  photo_url?: string | null;
}

// Card ki images (background + logo) isi file mai embed hain, alag se koi file rakhne ki zaroorat nahi.
const CARD_BG = 'data:image/webp;base64,';
const LOGO = 'data:image/webp;base64,';

const CARD_W = 1258;
const CARD_H = 685;
const CARD_RADIUS = 58;

const FONT = "'Roboto Condensed', 'Arial Narrow', 'Helvetica Neue', Arial, sans-serif";

/* ───────────────────────── FRONT ───────────────────────── */
// Background (card-front-bg.png) aapke diye hue design se bana hai.
// Us ke upar sirf member ka data, photo aur logo lagta hai.
export const CardFront = ({ member }: { member: CardMember }) => {
  const contact = member.phone || member.cnic || member.b_form || '—';

  // value ka center-y (design ki 4 plates ke hisab se)
  const fields: { value: string; cy: number }[] = [
    { value: member.name, cy: 280 },
    { value: member.father_name, cy: 362 },
    { value: member.id, cy: 444 },
    { value: contact, cy: 529 },
  ];

  const valueSize = (v: string) => (v.length > 30 ? 26 : v.length > 24 ? 30 : v.length > 18 ? 34 : 38);

  return (
    <div
      style={{
        position: 'relative',
        width: CARD_W,
        height: CARD_H,
        borderRadius: CARD_RADIUS,
        overflow: 'hidden',
        fontFamily: FONT,
        backgroundColor: '#d9c3a0',
      }}
    >
      {/* Design background */}
      {/* eslint-disable-next-line @next/next/no-img-element */}
      <img
        src={CARD_BG}
        alt=""
        style={{ position: 'absolute', inset: 0, width: '100%', height: '100%' }}
      />

      {/* Halka watermark logo (background) */}
      {/* eslint-disable-next-line @next/next/no-img-element */}
      <img
        src={LOGO}
        alt=""
        style={{ position: 'absolute', left: 560, top: 150, width: 480, opacity: 0.05 }}
      />

      {/* Logo (left navy panel) */}
      {/* eslint-disable-next-line @next/next/no-img-element */}
      <img
        src={LOGO}
        alt="Logo"
        style={{ position: 'absolute', left: 22, top: 142, width: 394, height: 394, objectFit: 'contain' }}
      />

      {/* Field values */}
      {fields.map((f, i) => (
        <div
          key={i}
          style={{
            position: 'absolute',
            left: 537,
            top: f.cy - 24,
            width: 370,
            height: 48,
            lineHeight: '48px',
            fontSize: valueSize(f.value),
            color: '#2a2320',
            whiteSpace: 'nowrap',
            overflow: 'hidden',
            textOverflow: 'ellipsis',
          }}
        >
          {f.value}
        </div>
      ))}

      {/* Photo (design ke frame ke andar) */}
      <div
        style={{
          position: 'absolute',
          left: 1003,
          top: 249,
          width: 172,
          height: 264,
          overflow: 'hidden',
          backgroundColor: '#e3d2b4',
        }}
      >
        {member.photo_url && (
          // eslint-disable-next-line @next/next/no-img-element
          <img
            src={member.photo_url}
            alt="Member"
            crossOrigin="anonymous"
            style={{ width: '100%', height: '100%', objectFit: 'cover', objectPosition: 'center top', display: 'block' }}
          />
        )}
      </div>
    </div>
  );
};

/* ───────────────────────── BACK ───────────────────────── */
export const CardBack = () => (
  <div
    style={{
      position: 'relative',
      width: CARD_W,
      height: CARD_H,
      borderRadius: CARD_RADIUS,
      overflow: 'hidden',
      background: 'linear-gradient(135deg, #25398a 0%, #14205f 100%)',
      fontFamily: FONT,
    }}
  >
    <svg width={CARD_W} height={CARD_H} style={{ position: 'absolute', inset: 0 }}>
      <defs>
        <pattern id="islamicBack" width="60" height="60" patternUnits="userSpaceOnUse">
          <path d="M30 3 L57 30 L30 57 L3 30 Z" fill="none" stroke="#ffffff" strokeOpacity="0.06" strokeWidth="1.4" />
          <circle cx="30" cy="30" r="12" fill="none" stroke="#ffffff" strokeOpacity="0.06" strokeWidth="1.4" />
        </pattern>
        <linearGradient id="silverBack" x1="0" y1="0" x2="1" y2="0">
          <stop offset="0" stopColor="#9a9aa2" />
          <stop offset="0.5" stopColor="#f7f5f0" />
          <stop offset="1" stopColor="#9a9aa2" />
        </linearGradient>
      </defs>
      <rect width={CARD_W} height={CARD_H} fill="url(#islamicBack)" />
      <rect x="22" y="22" width={CARD_W - 44} height={CARD_H - 44} rx="40" fill="none" stroke="#c9a35a" strokeOpacity="0.85" strokeWidth="2.5" />
      <rect x="36" y="36" width={CARD_W - 72} height={CARD_H - 72} rx="30" fill="none" stroke="url(#silverBack)" strokeOpacity="0.6" strokeWidth="1.5" />
    </svg>

    {/* eslint-disable-next-line @next/next/no-img-element */}
    <img
      src={LOGO}
      alt="Logo"
      style={{ position: 'absolute', left: (CARD_W - 400) / 2, top: 62, width: 400, height: 400, objectFit: 'contain' }}
    />
    <div
      style={{
        position: 'absolute', left: 0, right: 0, top: 488,
        textAlign: 'center', color: '#f2d98a', fontWeight: 700,
        fontSize: 40, lineHeight: 1.2, letterSpacing: 1,
      }}
    >
      NALIYA MANDWI JUNAGADH
      <br />
      MUSLIM WELFARE JAMAT
    </div>
  </div>
);

/* ───────────────────────── MODAL ───────────────────────── */
interface MemberCardModalProps {
  member: CardMember;
  onClose: () => void;
}

export default function MemberCardModal({ member, onClose }: MemberCardModalProps) {
  const frontRef = useRef<HTMLDivElement>(null);
  const backRef = useRef<HTMLDivElement>(null);
  const boxRef = useRef<HTMLDivElement>(null);
  const [scale, setScale] = useState(0.6);
  const [busy, setBusy] = useState(false);

  // Preview ko screen ki width ke hisab se scale karo
  useEffect(() => {
    const el = boxRef.current;
    if (!el) return;
    const ro = new ResizeObserver(() => {
      const w = el.clientWidth;
      if (w > 0) setScale(Math.min(1, w / CARD_W));
    });
    ro.observe(el);
    return () => ro.disconnect();
  }, []);

  const capture = async (node: HTMLDivElement | null): Promise<string | null> => {
    if (!node) return null;
    return toPng(node, {
      width: CARD_W,
      height: CARD_H,
      pixelRatio: 2,
      style: { transform: 'none' },
      backgroundColor: 'transparent',
    });
  };

  const download = async (side: 'front' | 'back') => {
    try {
      setBusy(true);
      const url = await capture(side === 'front' ? frontRef.current : backRef.current);
      if (!url) return;
      const a = document.createElement('a');
      a.href = url;
      a.download = `${member.id}-card-${side}.png`;
      a.click();
    } catch (err) {
      console.error(err);
      alert('Card download nahi ho saka. Dobara koshish karein.');
    } finally {
      setBusy(false);
    }
  };

  const printCard = async () => {
    // Popup blocker se bachne ke liye window pehle kholo
    const w = window.open('', '_blank', 'width=900,height=700');
    if (!w) {
      alert('Popup block hai. Browser mai popup allow karein.');
      return;
    }
    w.document.write('<p style="font-family:sans-serif">Card tayyar ho raha hai...</p>');
    try {
      setBusy(true);
      const front = await capture(frontRef.current);
      const back = await capture(backRef.current);
      w.document.open();
      w.document.write(`<!doctype html><html><head><title>${member.id} Card</title>
<style>
  @page { size: 85.6mm 46.6mm; margin: 0; }
  * { margin: 0; padding: 0; box-sizing: border-box; }
  html, body { background: #fff; }
  .page { width: 85.6mm; height: 46.6mm; page-break-after: always; overflow: hidden; }
  .page:last-child { page-break-after: auto; }
  img { width: 85.6mm; height: 46.6mm; display: block; }
</style></head><body>
<div class="page"><img src="${front}" /></div>
<div class="page"><img src="${back}" /></div>
<script>window.onload = function(){ setTimeout(function(){ window.print(); }, 300); };<\/script>
</body></html>`);
      w.document.close();
    } catch (err) {
      console.error(err);
      w.close();
      alert('Print ke liye card tayyar nahi ho saka.');
    } finally {
      setBusy(false);
    }
  };

  const btn = (bg: string): React.CSSProperties => ({
    padding: '9px 16px',
    border: 'none',
    borderRadius: 8,
    backgroundColor: bg,
    color: 'white',
    fontWeight: 600,
    fontSize: '0.88rem',
    cursor: busy ? 'not-allowed' : 'pointer',
    opacity: busy ? 0.7 : 1,
  });

  return (
    <div
      style={{
        position: 'fixed', inset: 0, backgroundColor: 'rgba(0,0,0,0.55)', zIndex: 300,
        display: 'flex', alignItems: 'center', justifyContent: 'center',
        padding: 'clamp(0.5rem, 3vw, 1rem)',
      }}
    >
      <div
        style={{
          backgroundColor: 'var(--white, #fff)', borderRadius: 12,
          padding: 'clamp(0.9rem, 3vw, 1.5rem)', width: '100%', maxWidth: 760,
          maxHeight: '94vh', overflowY: 'auto', boxShadow: '0 8px 32px rgba(0,0,0,0.3)',
        }}
      >
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '1rem' }}>
          <h2 style={{ fontSize: '1.15rem', margin: 0 }}>🪪 Member Card — {member.id}</h2>
          <button onClick={onClose} style={{ ...btn('#757575'), padding: '6px 12px' }}>✕ Close</button>
        </div>

        <div ref={boxRef} style={{ width: '100%' }}>
          {[
            { key: 'front', title: 'Front', ref: frontRef, node: <CardFront member={member} /> },
            { key: 'back', title: 'Back', ref: backRef, node: <CardBack /> },
          ].map(item => (
            <div key={item.key} style={{ marginBottom: '1rem' }}>
              <p style={{ fontSize: '0.8rem', fontWeight: 700, color: '#666', margin: '0 0 6px' }}>{item.title}</p>
              <div
                style={{
                  width: CARD_W * scale, height: CARD_H * scale,
                  boxShadow: '0 4px 14px rgba(0,0,0,0.25)', borderRadius: CARD_RADIUS * scale, overflow: 'hidden',
                }}
              >
                <div
                  ref={item.ref}
                  style={{ width: CARD_W, height: CARD_H, transform: `scale(${scale})`, transformOrigin: 'top left' }}
                >
                  {item.node}
                </div>
              </div>
            </div>
          ))}
        </div>

        <div style={{ display: 'flex', gap: '0.6rem', flexWrap: 'wrap' }}>
          <button disabled={busy} onClick={() => download('front')} style={btn('#1b2a6b')}>⬇️ Front PNG</button>
          <button disabled={busy} onClick={() => download('back')} style={btn('#1b2a6b')}>⬇️ Back PNG</button>
          <button disabled={busy} onClick={printCard} style={btn('#2e7d32')}>🖨️ Print (Front + Back)</button>
        </div>
      </div>
    </div>
  );
}